import sys

MOD = 1_000_000_007

def fib(n: int) -> int:
    if n == 0:
        return 0
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * ((b << 1) - a) % MOD
        d = (a * a + b * b) % MOD
        if bit == '0':
            a, b = c, d
        else:
            a, b = d, (c + d) % MOD
    return a

if __name__ == '__main__':
    print(fib(int(sys.argv[1])))

