import sys
from functools import cache

MOD = 1_000_000_007
PISANO = 2_000_000_016

@cache
def _fib_pair(n: int):
    if n == 0:
        return (0, 1)
    a, b = _fib_pair(n >> 1)
    c = a * ((b << 1) - a) % 1_000_000_007
    d = (a * a + b * b) % 1_000_000_007
    if n & 1:
        return (d, (c + d) % 1_000_000_007)
    return (c, d)

@cache
def fib(n: int) -> int:
    return _fib_pair(n % 2_000_000_016)[0]

if __name__ == '__main__':
    print(fib(int(sys.argv[1])))
